test_that("manifest validates and round trips", {m<-new_sblrbench_manifest("s","a",0L,1L,sblrbench_commit=NA_character_,sblr_commit="abc",genotype_source="generated");p<-tempfile(fileext=".json");write_sblrbench_manifest(m,p);z<-read_sblrbench_manifest(p);expect_identical(z$schema_version,1L);expect_identical(z$study,"s");expect_warning(expect_true(is.na(sblrbench_git_commit(tempfile()))),"unavailable");bad<-m;bad$runtime<-matrix(1);expect_error(validate_sblrbench_manifest(bad),"compact")})
